import sys
import types

import numpy as np
import pytest

from benchmark_core import dataset_crypto as dc


@pytest.fixture
def key():
    return dc.decode_key(dc.generate_key())


@pytest.fixture
def arrays():
    rng = np.random.default_rng(0)
    return rng.normal(size=(50, 4)).astype(np.float32), rng.integers(0, 3, size=50).astype(np.int64)


@pytest.fixture(autouse=True)
def no_cached_key(monkeypatch):
    monkeypatch.setattr(dc, "_cached_key", None)
    monkeypatch.delenv(dc.KEY_ENV_VAR, raising=False)
    # A None entry makes the import fail, so a real _bundled_key.py generated by
    # `just bundle-key` cannot leak into the tests. _bundle() overrides it.
    monkeypatch.setitem(sys.modules, "benchmark_core._bundled_key", None)


def test_roundtrip(key, arrays):
    X, y = arrays
    blob = dc.encrypt_arrays(X, y, "ds01", key)
    X2, y2, n_classes = dc.decrypt_arrays(blob, "ds01", key)
    np.testing.assert_array_equal(X, X2)
    np.testing.assert_array_equal(y, y2)
    assert n_classes == int(y.max()) + 1


def test_ciphertext_does_not_contain_plaintext(key, arrays):
    X, y = arrays
    assert X.tobytes()[:64] not in dc.encrypt_arrays(X, y, "ds01", key)


def test_wrong_key_rejected(key, arrays):
    blob = dc.encrypt_arrays(*arrays, "ds01", key)
    with pytest.raises(ValueError, match="decryption failed"):
        dc.decrypt_arrays(blob, "ds01", dc.decode_key(dc.generate_key()))


def test_wrong_dataset_id_rejected(key, arrays):
    blob = dc.encrypt_arrays(*arrays, "ds01", key)
    with pytest.raises(ValueError, match="decryption failed"):
        dc.decrypt_arrays(blob, "ds02", key)


def test_corrupted_file_rejected(key, arrays):
    blob = bytearray(dc.encrypt_arrays(*arrays, "ds01", key))
    blob[-1] ^= 0xFF
    with pytest.raises(ValueError, match="decryption failed"):
        dc.decrypt_arrays(bytes(blob), "ds01", key)
    with pytest.raises(ValueError, match="not an encrypted dataset"):
        dc.decrypt_arrays(b"plain csv,data\n", "ds01", key)


def test_invalid_arrays_rejected(key, arrays):
    X, y = arrays
    with pytest.raises(ValueError, match="float32"):
        dc.encrypt_arrays(X.astype(np.float64), y, "ds01", key)
    X_nan = X.copy()
    X_nan[0, 0] = np.nan
    with pytest.raises(ValueError, match="NaN"):
        dc.encrypt_arrays(X_nan, y, "ds01", key)
    with pytest.raises(ValueError, match="rows"):
        dc.encrypt_arrays(X, y[:-1], "ds01", key)


def test_missing_key(arrays):
    with pytest.raises(ValueError, match=dc.KEY_ENV_VAR):
        dc.get_key()


def test_bad_key_text():
    with pytest.raises(ValueError, match="bytes"):
        dc.decode_key("c2hvcnQ=")


def test_key_removed_from_environment_after_read(monkeypatch, tmp_path, key, arrays):
    path = tmp_path / "ds01.bin"
    path.write_bytes(dc.encrypt_arrays(*arrays, "ds01", key))
    monkeypatch.setenv(dc.KEY_ENV_VAR, dc.base64.urlsafe_b64encode(key).decode())

    dc.load_encrypted(path, "ds01")
    assert dc.KEY_ENV_VAR not in dc.os.environ
    # A second dataset in the same process still loads from the cached key.
    dc.load_encrypted(path, "ds01")


def _bundle(monkeypatch, key):
    module = types.ModuleType("benchmark_core._bundled_key")
    module.KEY = dc.base64.urlsafe_b64encode(key).decode()
    monkeypatch.setitem(sys.modules, "benchmark_core._bundled_key", module)


def test_bundled_key_used_without_environment(monkeypatch, tmp_path, key, arrays):
    path = tmp_path / "ds01.bin"
    path.write_bytes(dc.encrypt_arrays(*arrays, "ds01", key))
    _bundle(monkeypatch, key)

    X, _, _ = dc.load_encrypted(path, "ds01")
    np.testing.assert_array_equal(X, arrays[0])


def test_bundled_key_wins_and_environment_still_removed(monkeypatch, key):
    _bundle(monkeypatch, key)
    monkeypatch.setenv(dc.KEY_ENV_VAR, dc.generate_key())

    assert dc.get_key() == key
    assert dc.KEY_ENV_VAR not in dc.os.environ
